-- public.school_focus(p_world uuid, p_uid uuid, p_school text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.school_focus(p_world uuid, p_uid uuid, p_school text)
 RETURNS item
 LANGUAGE sql
 STABLE
AS $function$
  select i.* from item i
   where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid
     and i.def = 'focus' and lower(coalesce(i.extra, '')) in (select st.gem from school_stone st where st.school = p_school)
     and coalesce(i.dmg, 0) < 100 and not i.locked
   order by i.ql desc nulls last, i.dmg, i.id limit 1
$function$
